233	function makeCategoryTicks(axis: Axis, tickModel: AxisBaseModel) {
234	    const ticksCache = ensureCategoryTickCache(axis);
235	    const optionTickInterval = getOptionCategoryInterval(tickModel);
236	    const result = axisCacheGet(ticksCache, optionTickInterval);
237	
238	    if (result) {
239	        return result;
240	    }
241	
242	    let ticks: number[];
243	    let tickCategoryInterval;
244	
245	    // Optimize for the case that large category data and no label displayed,
246	    // we should not return all ticks.
247	    if (!tickModel.get('show') || axis.scale.isBlank()) {
248	        ticks = [];
249	    }
250	
251	    if (zrUtil.isFunction(optionTickInterval)) {
252	        ticks = makeLabelsByCustomizedCategoryInterval(axis, optionTickInterval, true);
253	    }
254	    // Always use label interval by default despite label show. Consider this
255	    // scenario, Use multiple grid with the xAxis sync, and only one xAxis shows
256	    // labels. `splitLine` and `axisTick` should be consistent in this case.
257	    else if (optionTickInterval === 'auto') {
258	        const labelsResult = makeCategoryLabelsActually(
259	            axis, axis.getLabelModel(), createAxisLabelsComputingContext(AxisTickLabelComputingKind.determine)
260	        );
261	        tickCategoryInterval = labelsResult.labelCategoryInterval;
262	        ticks = zrUtil.map(labelsResult.labels, function (labelItem) {
263	            return labelItem.tickValue;
264	        });
265	    }
266	    else {
267	        tickCategoryInterval = optionTickInterval;
268	        ticks = makeLabelsByNumericCategoryInterval(axis, tickCategoryInterval, true);
269	    }
270	
271	    // Cache to avoid calling interval function repeatedly.
272	    return axisCacheSet(ticksCache, optionTickInterval, {
273	        ticks: ticks, tickCategoryInterval: tickCategoryInterval
274	    });
275	}
