299	/**
300	 * PENDING: refactor to JS Map? Because key can be a function or more complicated object, and
301	 * cache size always is small, and currently no JS Map object key polyfill, we use a simple
302	 * array cache instead of plain object hash.
303	 */
304	function initAxisCacheMethod<TCacheProp extends AxisInnerStoreCacheProp>(prop: TCacheProp) {
305	    return function ensureCache(axis: Axis): AxisInnerStore[TCacheProp] {
306	        return axisInner(axis)[prop] || (axisInner(axis)[prop] = {list: []});
307	    };
308	}
