475	function makeLabelsByNumericCategoryInterval(
476	    axis: Axis, categoryInterval: number
477	): AxisLabelInfoDetermined[];
478	function makeLabelsByNumericCategoryInterval(
479	    axis: Axis, categoryInterval: number, onlyTick: false
480	): AxisLabelInfoDetermined[];
481	function makeLabelsByNumericCategoryInterval(
482	    axis: Axis, categoryInterval: number, onlyTick: true
483	): number[];
484	function makeLabelsByNumericCategoryInterval(
485	    axis: Axis, categoryInterval: number, onlyTick?: boolean
486	) {
487	    const labelFormatter = makeLabelFormatter(axis);
488	    const ordinalScale = axis.scale as OrdinalScale;
489	    const ordinalExtent = ordinalScale.getExtent();
490	    const labelModel = axis.getLabelModel();
491	    const result: (AxisLabelInfoDetermined | number)[] = [];
492	
493	    // TODO: axisType: ordinalTime, pick the tick from each month/day/year/...
494	
495	    const step = Math.max((categoryInterval || 0) + 1, 1);
496	    let startTick = ordinalExtent[0];
497	    const tickCount = ordinalScale.count();
498	
499	    // Calculate start tick based on zero if possible to keep label consistent
500	    // while zooming and moving while interval > 0. Otherwise the selection
501	    // of displayable ticks and symbols probably keep changing.
502	    // 3 is empirical value.
503	    if (startTick !== 0 && step > 1 && tickCount / step > 2) {
504	        startTick = Math.round(Math.ceil(startTick / step) * step);
505	    }
506	
507	    // (1) Only add min max label here but leave overlap checking
508	    // to render stage, which also ensure the returned list
509	    // suitable for splitLine and splitArea rendering.
510	    // (2) Scales except category always contain min max label so
511	    // do not need to perform this process.
512	    const showAllLabel = shouldShowAllLabels(axis);
513	    const includeMinLabel = labelModel.get('showMinLabel') || showAllLabel;
514	    const includeMaxLabel = labelModel.get('showMaxLabel') || showAllLabel;
515	
516	    if (includeMinLabel && startTick !== ordinalExtent[0]) {
517	        addItem(ordinalExtent[0]);
518	    }
519	
520	    // Optimize: avoid generating large array by `ordinalScale.getTicks()`.
521	    let tickValue = startTick;
522	    for (; tickValue <= ordinalExtent[1]; tickValue += step) {
523	        addItem(tickValue);
524	    }
525	
526	    if (includeMaxLabel && tickValue - step !== ordinalExtent[1]) {
527	        addItem(ordinalExtent[1]);
528	    }
529	
530	    function addItem(tickValue: number) {
531	        const tickObj = { value: tickValue };
532	        result.push(onlyTick
533	            ? tickValue
534	            : {
535	                formattedLabel: labelFormatter(tickObj),
536	                rawLabel: ordinalScale.getLabel(tickObj),
537	                tickValue: tickValue,
538	                time: undefined,
539	                break: undefined,
540	            }
541	        );
542	    }
543	
544	    return result;
545	}
