547	type CategoryIntervalCb = (tickVal: number, rawLabel: string) => boolean;
548	
549	// When interval is function, the result `false` means ignore the tick.
550	// It is time consuming for large category data.
551	function makeLabelsByCustomizedCategoryInterval(
552	    axis: Axis, categoryInterval: CategoryIntervalCb
553	): AxisLabelInfoDetermined[];
554	function makeLabelsByCustomizedCategoryInterval(
555	    axis: Axis, categoryInterval: CategoryIntervalCb, onlyTick: false
556	): AxisLabelInfoDetermined[];
557	function makeLabelsByCustomizedCategoryInterval(
558	    axis: Axis, categoryInterval: CategoryIntervalCb, onlyTick: true
559	): number[];
560	function makeLabelsByCustomizedCategoryInterval(
561	    axis: Axis, categoryInterval: CategoryIntervalCb, onlyTick?: boolean
562	) {
563	    const ordinalScale = axis.scale;
564	    const labelFormatter = makeLabelFormatter(axis);
565	    const result: (AxisLabelInfoDetermined | number)[] = [];
566	
567	    zrUtil.each(ordinalScale.getTicks(), function (tick) {
568	        const rawLabel = ordinalScale.getLabel(tick);
569	        const tickValue = tick.value;
570	        if (categoryInterval(tick.value, rawLabel)) {
571	            result.push(
572	                onlyTick
573	                ? tickValue
574	                : {
575	                    formattedLabel: labelFormatter(tick),
576	                    rawLabel: rawLabel,
577	                    tickValue: tickValue,
578	                    time: undefined,
579	                    break: undefined,
580	                }
581	            );
582	        }
583	    });
584	
585	    return result;
586	}
