252	    calcNiceExtent(
253	        opt?: {
254	            splitNumber?: number,
255	            fixMin?: boolean,
256	            fixMax?: boolean,
257	            minInterval?: number,
258	            maxInterval?: number
259	        }
260	    ): void {
261	        const extent = this.getExtent();
262	        // If extent start and end are same, expand them
263	        if (extent[0] === extent[1]) {
264	            // Expand extent
265	            extent[0] -= ONE_DAY;
266	            extent[1] += ONE_DAY;
267	        }
268	        // If there are no data and extent are [Infinity, -Infinity]
269	        if (extent[1] === -Infinity && extent[0] === Infinity) {
270	            const d = new Date();
271	            extent[1] = +new Date(d.getFullYear(), d.getMonth(), d.getDate());
272	            extent[0] = extent[1] - ONE_DAY;
273	        }
274	        this._innerSetExtent(extent[0], extent[1]);
275	
276	        this.calcNiceTicks(opt.splitNumber, opt.minInterval, opt.maxInterval);
277	    }
